mapper.select:
SELECT t2.user_name AS username FROM bs_wx_user_link t LEFT JOIN bs_wx_user t1 ON t1.union_id = t.union_id LEFT JOIN sys_user t2 ON t2.user_id = t.user_id WHERE t.union_id = #{unionId}
AND t2.user_name = #{userName}
AND t.delete_flag = '0' and t2.DEL_FLAG = '0' and t2.STATUS = '0' LIMIT 1

SELECT count(1)
FROM bs_wx_user
WHERE union_id = #{unionId}

mapper.update:
UPDATE bs_wx_user
open_id = #{openId}, mini_open_id = #{miniOpenId}, nick_name = #{nickName}, delete_flag = '0', update_time = now()
WHERE union_id = #{unionId}

update bs_wx_user_link t
set t.industry_code = #{tradeId}
WHERE t.union_id = #{unionId}
  AND t.is_active = 'Y'

update bs_wx_user_link
set IS_ACTIVE = 'N'
where USER_ID = #{userId}

update bs_wx_user_link t
set RECEIVE_MSG = #{receiveMsg}
WHERE t.union_id = #{unionId}
  AND t.is_active = 'Y'
